/*commonApproval.buyerNewPassRecvList*/
SELECT
count(1) TOTAL_CNT
DISTINCT 0 No, --[00] Y.COMPANY, --[01] Y.DOCU_NO, --[02] Y.DOCU_TITLE, --[03] Y.ATTACH_CNT, --[04] Y.GUBUN, --[05] Y.START_DATE, --[06] Y.NEXT_USER_NM, --[07] Y.DOCU_KN, --[08] Y.ADD_USER_ID, --[09] Y.PASS_TP, --[10] Y.PASS_KN, --[11] Y.USER_NM, --[12] Y.NEXT_USER_ID, --[13] Y.EXTIF_TP_TEXT, --[14] Y.EXTIF_TP, --[15] NVL(Y.ORDER_DEPT,(SELECT D.TEXT1 FROM ICOMCOD2 D WHERE D.COMPANY_CODE=Y.COMPANY AND D.TYPE='C001' AND D.CODE=Y.DEPARTMENT)) ORDER_DEPT, --[16] Y.ITEM_CNT, --[17] Y.ORDER_AMT, --[18] NVL(Y.ORDER_DEPT_CD,Y.DEPARTMENT) ORDER_DEPT_CD, --[19] Y.KEY1, --[20] Y.EXTIFNO, --[21] Y.EXTIFCOUNT, --[22] (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = Y.COMPANY) AS COMPANY_NAME, Y.DOC_TYPE FROM( SELECT ROWNUM NUM, X.COMPANY, X.DOCU_NO, X.DOCU_TITLE, X.ATTACH_CNT, X.GUBUN, X.START_DATE, X.NEXT_USER_NM, X.DOCU_KN, X.ADD_USER_ID, X.PASS_TP, X.PASS_KN, X.USER_NM, X.NEXT_USER_ID, X.EXTIF_TP_TEXT, X.EXTIF_TP, X.ITEM_CNT, X.ORDER_AMT, X.ORDER_DEPT, X.ORDER_DEPT_CD, X.KEY1, X.EXTIFNO, X.EXTIFCOUNT, (SELECT DEPARTMENT FROM ICOMLUSR WHERE USER_ID = X.USER_ID) DEPARTMENT, X.DOC_TYPE FROM( SELECT A.COMPANY, A.DOCU_NO, A.DOCU_TITLE, A.ATTACH_CNT, DECODE(C.PASS_TP,'1','결재문서','2','참조문서','3','합의문서') GUBUN, TO_CHAR(A.START_DATE, 'YYYY/MM/DD' ) START_DATE, START_DATE START_DATE2, DECODE(#{USERID}, B.USER_ID, '결재요망', (SELECT CODE2 FROM ICOMCOD3 WHERE TYPE = 'M-APPR' AND FLAG = 'Y' AND CODE2 = #{USERID} AND CODE1 = B.USER_ID), '결재요망', (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = B.USER_ID)) AS NEXT_USER_NM, A.DOCU_KN, A.USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.USER_ID) ADD_USER_ID, C.PASS_TP, NVL(C.PASS_KN,'0') PASS_KN, A.USER_NM USER_NM, B.USER_ID AS NEXT_USER_ID, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'APPR' AND CODE = A.EXTIF_TP) AS EXTIF_TP_TEXT, A.EXTIF_TP AS EXTIF_TP, DECODE(TRGW.DOC_NAME,'PR', (SELECT COUNT(*) FROM ICOMPRDT WHERE BUYER = TRGW.COM_CODE AND PR_NO = TRGW.KEY_1 AND STATUS ^= 'D'), 'PX', (SELECT COUNT(*) FROM ICOMPRDT WHERE BUYER = TRGW.COM_CODE AND REF_NO = TRGW.KEY_1 AND STATUS ^= 'D'),NULL) AS ITEM_CNT, DECODE(TRGW.DOC_NAME,'PR', (SELECT SUM(TARGET_QTY*TARGET_PRICE) FROM ICOMPRDT WHERE BUYER = TRGW.COM_CODE AND PR_NO = TRGW.KEY_1 AND STATUS ^= 'D'), 'PX', (SELECT SUM(RECV_QTY*TARGET_PRICE) FROM ICOMPRDT WHERE BUYER = TRGW.COM_CODE AND REF_NO = TRGW.KEY_1 AND STATUS ^= 'D'),NULL) AS ORDER_AMT, DECODE(TRGW.DOC_NAME,'PR', (SELECT MAX(COD2.TEXT1)||DECODE(COUNT(DISTINCT CHANGE_USER_DEPT),1,NULL, ' 외 '||TO_CHAR(COUNT(DISTINCT CHANGE_USER_DEPT)-1)||'개') FROM ICOMPRDT, ICOMCOD2 COD2 WHERE BUYER = TRGW.COM_CODE AND PR_NO = TRGW.KEY_1 AND STATUS ^= 'D' AND BUYER = COD2.COMPANY_CODE AND COD2.TYPE = 'C001' AND COD2.CODE =CHANGE_USER_DEPT ), 'PX', (SELECT MAX(COD2.TEXT1)||DECODE(COUNT(DISTINCT CHANGE_USER_DEPT),1,NULL, ' 외 '||TO_CHAR(COUNT(DISTINCT CHANGE_USER_DEPT)-1)||'건') FROM ICOMPRDT, ICOMCOD2 COD2 WHERE BUYER = TRGW.COM_CODE AND REF_NO = TRGW.KEY_1 AND STATUS ^= 'D' AND BUYER = COD2.COMPANY_CODE AND COD2.TYPE = 'C001' AND COD2.CODE =CHANGE_USER_DEPT),NULL) AS ORDER_DEPT, DECODE(TRGW.DOC_NAME,'PR', (SELECT MAX( CHANGE_USER_DEPT) FROM ICOMPRDT, ICOMCOD2 COD2 WHERE BUYER = TRGW.COM_CODE AND PR_NO = TRGW.KEY_1 AND STATUS ^= 'D' AND BUYER = COD2.COMPANY_CODE AND COD2.TYPE = 'C001' AND COD2.CODE =CHANGE_USER_DEPT ), 'PX', (SELECT MAX(CHANGE_USER_DEPT) FROM ICOMPRDT, ICOMCOD2 COD2 WHERE BUYER = TRGW.COM_CODE AND REF_NO = TRGW.KEY_1 AND STATUS ^= 'D' AND BUYER = COD2.COMPANY_CODE AND COD2.TYPE = 'C001' AND COD2.CODE =CHANGE_USER_DEPT),NULL) AS ORDER_DEPT_CD, TRGW.KEY_1 AS KEY1, A.EXTIF_NO AS EXTIFNO, A.EXTIF_COUNT AS EXTIFCOUNT, NVL((SELECT DOC_TYPE FROM ICOMPRHD WHERE BUYER = A.COMPANY AND PR_NO = TRGW.KEY_1 AND A.EXTIF_TP = 'PR'),'N') AS DOC_TYPE
FROM ICOGDOCU A, ICOGPASSLN B, (SELECT Y.COMPANY, Y.DOCU_NO, Y.PASS_TP, Y.PASS_KN,Y.ORDER_NO FROM ICOGDOCU X, ICOGPASSLN Y WHERE X.COMPANY IN (SELECT BUYER FROM ICOMCOD3 WHERE TYPE = 'M-APPR' AND FLAG = 'Y' AND CODE2 = #{USERID} UNION SELECT #{BUYER} FROM DUAL) AND X.START_DATE BETWEEN to_date(#{startDate},'YYYY/MM/DD') AND to_date(#{endDate},'YYYY/MM/DD')+1 AND X.PASS_STATUS = '0' AND X.COMPANY=Y.COMPANY AND X.DOCU_NO=Y.DOCU_NO AND Y.USER_ID IN (SELECT CODE1 FROM ICOMCOD3 WHERE TYPE = 'M-APPR' AND FLAG = 'Y' AND CODE2 = #{USERID} UNION SELECT #{USERID} FROM DUAL) AND Y.ORDER_NO > 1 AND Y.DISPLAY_YN = 'Y') C ,ICOMTRGW TRGW WHERE ((C.PASS_TP = '1' AND A.DOCU_NO = C.DOCU_NO AND A.COMPANY = C.COMPANY AND A.PASS_STATUS = '0' AND C.PASS_KN IS NULL ) OR (C.PASS_TP = '3' AND A.DOCU_NO = C.DOCU_NO AND A.COMPANY = C.COMPANY AND A.PASS_STATUS = '0' AND C.PASS_KN IS NULL)) AND A.COMPANY = B.COMPANY AND A.DOCU_NO = B.DOCU_NO AND A.CUR_ORDER_NO = B.ORDER_NO AND A.COMPANY = TRGW.COM_CODE AND A.DOCU_NO = TRGW.TARGET AND C.COMPANY = A.COMPANY AND C.DOCU_NO = A.DOCU_NO AND C.COMPANY = TRGW.COM_CODE AND C.DOCU_NO = TRGW.TARGET AND C.PASS_TP IN ('1', '3')
AND B.USER_ID IN (SELECT CODE1 FROM ICOMCOD3 WHERE TYPE = 'M-APPR' AND FLAG = 'Y' AND CODE2 = #{USERID} UNION SELECT #{USERID} FROM DUAL)
AND A.USER_ID = #{st_po_user_id}
AND A.USER_NM like '%'||#{st_drafter} ||'%'
AND A.EXTIF_TP =#{st_gubun}
AND A.DOCU_TITLE LIKE '%'||#{st_subject} ||'%'
AND A.COMPANY = #{st_buyer_list}
ORDER BY START_DATE2 DESC ) X )Y WHERE Y.NUM BETWEEN #{startrow} AND #{endrow}

/*commonApproval.buyerNewPassCompleteList*/
SELECT
count(1) TOTAL_CNT
0 No, --[00] Y.COMPANY, --[01] Y.DOCU_NO, --[02] Y.DOCU_TITLE, --[03] Y.ATTACH_CNT, --[04] Y.PASS_STATUS, --[05] Y.START_DATE, --[06] Y.NEXT_USER_NM, --[07] Y.DOCU_KN, --[08] Y.ADD_USER_ID, --[09] Y.PASS_TP, --[10] Y.PASS_KN, --[11] Y.USER_NM, --[12] Y.GUBUN, --[13] Y.EXTIF_TP_TEXT, --[14] Y.EXTIF_TP, --[15] (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = Y.COMPANY) AS COMPANY_NAME FROM( SELECT ROWNUM NUM, X.COMPANY, X.DOCU_NO, X.DOCU_TITLE, X.ATTACH_CNT, X.PASS_STATUS, X.START_DATE, X.NEXT_USER_NM, X.DOCU_KN, X.ADD_USER_ID, X.PASS_TP, X.PASS_KN, X.USER_NM, X.GUBUN, X.EXTIF_TP_TEXT, X.EXTIF_TP FROM( SELECT A.COMPANY, A.DOCU_NO, A.DOCU_TITLE, A.ATTACH_CNT, DECODE(A.PASS_STATUS,'0','결재진행중', '1','반려', '2','참조진행중', '3','결재완료', '4','상신취소', ' ' ) PASS_STATUS, TO_CHAR(A.START_DATE, 'YYYY/MM/DD HH24:MI:SS' ) START_DATE, DECODE(A.PASS_STATUS,'0',(SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = B.USER_ID),' ') NEXT_USER_NM, A.DOCU_KN, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.USER_ID) AS ADD_USER_ID, C.PASS_TP, NVL(C.PASS_KN,'0') AS PASS_KN, A.USER_NM AS USER_NM, DECODE(C.PASS_TP,'2','참조', DECODE(C.PASS_KN ,NULL,'미결재' ,'1' ,'결재' ,'3' ,'반려' ,'4' ,'미결재')) GUBUN, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'APPR' AND CODE = A.EXTIF_TP) AS EXTIF_TP_TEXT, A.EXTIF_TP AS EXTIF_TP
FROM ICOGDOCU A, ICOGPASSLN B, (SELECT COMPANY, DOCU_NO, PASS_TP, PASS_KN FROM ICOGPASSLN WHERE USER_ID IN (SELECT CODE1 FROM ICOMCOD3 WHERE TYPE = 'M-APPR' AND FLAG = 'Y' AND CODE2 = #{USERID} UNION SELECT #{USERID} FROM DUAL) AND COMPANY IN (SELECT BUYER FROM ICOMCOD3 WHERE TYPE = 'M-APPR' AND FLAG = 'Y' AND CODE2 = #{USERID} UNION SELECT #{BUYER} FROM DUAL) AND ORDER_NO > 1 AND DISPLAY_YN = 'Y') C WHERE ((C.PASS_TP IN ('1', '3') AND A.DOCU_NO = C.DOCU_NO AND A.COMPANY = C.COMPANY AND C.PASS_KN IS NOT NULL ) OR (C.PASS_TP IN ('1', '3') AND A.DOCU_NO = C.DOCU_NO AND A.COMPANY = C.COMPANY AND A.PASS_STATUS <> '0' AND C.PASS_KN IS NULL) OR ( C.PASS_TP = '2' AND A.DOCU_NO = C.DOCU_NO AND A.COMPANY = C.COMPANY AND A.PASS_STATUS <> '0') ) AND A.COMPANY = B.COMPANY AND A.DOCU_NO = B.DOCU_NO AND A.CUR_ORDER_NO = B.ORDER_NO AND TO_CHAR(START_DATE,'YYYYMMDD') BETWEEN replace(#{startDate},'/','') AND replace(#{endDate},'/','')
AND DECODE(C.PASS_TP,'2','2', DECODE(NVL(C.PASS_KN,'0'),'0','0' ,'1','1' ,'3','3' ,'4','0' )) = #{st_status1}
AND a.user_nm LIKE '%'||#{st_drafter}||'%'
AND A.EXTIF_TP = #{st_gubun}
AND A.PASS_STATUS = #{st_status}
AND A.COMPANY = #{st_buyer_list}
AND A.DOCU_TITLE LIKE '%'||#{st_subject}||'%' ORDER BY START_DATE DESC
) X )Y WHERE Y.NUM BETWEEN #{startrow} AND #{endrow}

/*commonApproval.buyerNewPassList_v2*/ SELECT Y.NUM AS NO, --[00] Y.COMPANY, --[01] Y.DOCU_NO, --[02] Y.DOCU_TITLE, --[03] Y.ATTACH_CNT, --[04] Y.PASS_STATUS, --[05] Y.START_DATE, --[06] Y.NEXT_USER_NM, --[07] Y.NEXT_USER_ID, Y.DOCU_KN, --[08] Y.ADD_USER_ID, --[09] Y.PASS_TP, --[10] Y.PASS_KN, --[11] Y.USER_NM, --[12] Y.GUBUN, --[13] Y.EXTIF_TP_TEXT, --[14] Y.EXTIF_TP, --[15] (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = Y.COMPANY) AS COMPANY_NAME, Y.PRICE, Y.DOC_TYPE FROM( SELECT ROWNUM NUM, X.COMPANY, X.DOCU_NO, X.DOCU_TITLE, X.ATTACH_CNT, X.PASS_STATUS, X.START_DATE, X.NEXT_USER_NM, X.NEXT_USER_ID, X.DOCU_KN, X.ADD_USER_ID, X.PASS_TP, X.PASS_KN, X.USER_NM, X.GUBUN, X.EXTIF_TP_TEXT, X.EXTIF_TP, CASE WHEN X.EXTIF_TP = 'PR' THEN NVL((SELECT SUM(TRUNC(NVL(A.TARGET_QTY,0) * NVL(A.TARGET_PRICE,0))) FROM ICOMPRDT A WHERE A.BUYER = X.COMPANY AND A.PR_NO = X.KEY_1 AND A.RECV_FLAG NOT IN ('GR','PR','RR') AND A.STATUS != 'D'),0) WHEN X.EXTIF_TP = 'PX' THEN NVL((SELECT SUM(TRUNC(NVL(A.TARGET_QTY,0) * NVL(A.TARGET_PRICE,0))) FROM ICOMPRDT A WHERE A.BUYER = X.COMPANY AND A.REF_NO = X.KEY_1 AND A.RECV_FLAG NOT IN ('GR','PR','RR') AND A.STATUS != 'D'),0) WHEN X.EXTIF_TP = 'NG' THEN 0 WHEN X.EXTIF_TP = 'NS' THEN NVL((SELECT SUM(A.ATOB_UNIT_PRICE) FROM KEPRQDT A WHERE A.BUYER IN (SELECT CODE2 FROM ICOMCOD3 WHERE BUYER = X.COMPANY AND TYPE = 'TGCM' AND CODE1 = X.USER_ID AND FLAG = 'Y' UNION SELECT X.COMPANY FROM DUAL) AND A.GW_NO = X.KEY_1 AND A.SO_CA_FLAG = 'SO' AND A.STATUS IN ('C','R') AND A.RECV_FLAG != 'GD' AND A.ATOB_SEND_FLAG = 'Y' ),0) END AS PRICE, X.DOC_TYPE FROM( SELECT A.COMPANY, A.DOCU_NO, A.DOCU_TITLE, A.ATTACH_CNT, DECODE(A.PASS_STATUS,'1','결재반려', '2','참조진행중', '3','결재완료', '4','상신취소', '0',CASE WHEN B.USER_ID IN (SELECT CODE1 FROM ICOMCOD3 WHERE TYPE = 'M-APPR' AND FLAG = 'Y' AND CODE2 = #{USERID} UNION SELECT #{USERID} FROM DUAL) THEN '결재대기' WHEN A.CUR_ORDER_NO = 2 AND A.USER_ID = #{USERID} AND B.REFER_DATE IS NULL THEN '상신완료' ELSE '결재진행중' END, ' ' ) PASS_STATUS, TO_CHAR(A.START_DATE, 'YYYY-MM-DD HH24:MI' ) START_DATE, DECODE(A.PASS_STATUS,'0',(SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = B.USER_ID),'') NEXT_USER_NM, B.USER_ID AS NEXT_USER_ID, A.DOCU_KN, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.USER_ID) AS ADD_USER_ID, D.PASS_TP, NVL(D.PASS_KN,'0') AS PASS_KN, A.USER_NM AS USER_NM, DECODE(D.PASS_TP,'2','참조' ,'1' ,'결재' ,'0' ,'상신' ,'3' , '합의') GUBUN, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'APPR' AND CODE = A.EXTIF_TP) AS EXTIF_TP_TEXT, A.EXTIF_TP AS EXTIF_TP, C.KEY_1, NVL((SELECT DOC_TYPE FROM ICOMPRHD WHERE BUYER = A.COMPANY AND PR_NO = C.KEY_1 AND A.EXTIF_TP = 'PR'),'N') AS DOC_TYPE, A.USER_ID FROM ICOGDOCU A, ICOGPASSLN B, ICOMTRGW C, (
SELECT COMPANY, DOCU_NO, PASS_TP, PASS_KN FROM ICOGPASSLN WHERE USER_ID IN (SELECT CODE1 FROM ICOMCOD3 WHERE TYPE = 'M-APPR' AND FLAG = 'Y' AND CODE2 = #{USERID} UNION SELECT #{USERID} FROM DUAL) AND COMPANY IN (SELECT BUYER FROM ICOMCOD3 WHERE TYPE = 'M-APPR' AND FLAG = 'Y' AND CODE2 = #{USERID} UNION SELECT #{BUYER} FROM DUAL) AND DISPLAY_YN = 'Y'
SELECT COMPANY, DOCU_NO, PASS_TP, PASS_KN FROM (SELECT COMPANY, DOCU_NO, PASS_TP, PASS_KN, ROW_NUMBER() OVER (PARTITION BY COMPANY, DOCU_NO ORDER BY DECODE(PASS_TP,'1',1,'3',2,'2',3,'0',4,5)) RN FROM ICOGPASSLN WHERE USER_ID IN (SELECT CODE1 FROM ICOMCOD3 WHERE TYPE = 'M-APPR' AND FLAG = 'Y' AND CODE2 = #{USERID} UNION SELECT #{USERID} FROM DUAL) AND COMPANY IN (SELECT BUYER FROM ICOMCOD3 WHERE TYPE = 'M-APPR' AND FLAG = 'Y' AND CODE2 = #{USERID} UNION SELECT #{BUYER} FROM DUAL) AND DISPLAY_YN = 'Y') WHERE RN = 1
) D WHERE A.DOCU_NO = D.DOCU_NO AND A.COMPANY = D.COMPANY AND A.COMPANY = B.COMPANY AND A.DOCU_NO = B.DOCU_NO AND A.CUR_ORDER_NO = B.ORDER_NO AND A.COMPANY = C.COM_CODE AND A.DOCU_NO = C.TARGET AND TO_CHAR(A.START_DATE,'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
AND D.PASS_TP = #{st_status1}
AND A.EXTIF_TP = #{st_gubun}
AND A.COMPANY = #{st_buyer_list}
AND (UPPER(A.DOCU_TITLE) LIKE UPPER('%'||#{st_keyword}||'%') OR UPPER(A.DOCU_CONT) LIKE UPPER('%'||#{st_keyword}||'%') OR UPPER(A.USER_NM) LIKE UPPER('%'||#{st_keyword}||'%') OR UPPER(A.USER_ID) LIKE UPPER('%'||#{st_keyword}||'%'))
AND UPPER(A.DOCU_TITLE) LIKE UPPER('%'||#{st_keyword}||'%')
AND UPPER(A.USER_NM) LIKE UPPER('%'||#{st_keyword}||'%')
AND UPPER(A.USER_ID) LIKE UPPER('%'||#{st_keyword}||'%')
AND UPPER(A.DOCU_CONT) LIKE UPPER('%'||#{st_keyword}||'%')
ORDER BY START_DATE DESC ) X WHERE 1=1
AND X.PASS_STATUS = #{st_status}
)Y

/*commonApproval.buyerNewPassSendList*/ SELECT
count(1) TOTAL_CNT
DISTINCT 0 No, --[00] Y.COMPANY, --[01] Y.DOCU_NO, --[02] Y.DOCU_TITLE, --[03] Y.ATTACH_CNT, --[04] Y.PASS_STATUS, --[05] Y.START_DATE, --[06] Y.NEXT_USER_NM, --[07] Y.DOCU_KN, --[08] Y.ADD_USER_ID, --[09] Y.PASS_TP, --[10] Y.PASS_KN, --[11] Y.USER_NM, --[12] Y.PASS_STATUS_CODE, --[13] Y.EXTIF_TP_TEXT, --[14] Y.EXTIF_TP --[15] FROM ( SELECT ROWNUM NUM, X.COMPANY, X.DOCU_NO, X.DOCU_TITLE, X.ATTACH_CNT, X.PASS_STATUS, X.START_DATE, X.NEXT_USER_NM, X.DOCU_KN, X.ADD_USER_ID, X.PASS_TP, X.PASS_KN, X.USER_NM, X.PASS_STATUS_CODE, X.EXTIF_TP_TEXT, X.EXTIF_TP FROM( SELECT A.COMPANY, A.DOCU_NO, A.DOCU_TITLE, A.ATTACH_CNT, DECODE(A.PASS_STATUS,'0','결재진행중', '1','반려', '2','참조진행중', '3','결재완료', '4','상신취소', ' ' ) PASS_STATUS, TO_CHAR(A.START_DATE, 'YYYY/MM/DD HH24:MI:SS' ) START_DATE, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = B.USER_ID) NEXT_USER_NM, A.DOCU_KN, A.USER_ID ADD_USER_ID, '1' PASS_TP, '1' PASS_KN, A.USER_NM USER_NM, A.PASS_STATUS AS PASS_STATUS_CODE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'APPR' AND CODE = A.EXTIF_TP) AS EXTIF_TP_TEXT, A.EXTIF_TP AS EXTIF_TP
FROM ICOGDOCU A, ICOGPASSLN B, ICOGPASSLN C WHERE A.USER_ID =#{USERID} AND A.COMPANY = #{BUYER} AND C.USER_ID = A.USER_ID AND C.COMPANY = A.COMPANY AND C.DOCU_NO = A.DOCU_NO AND C.DISPLAY_YN = 'Y' AND B.COMPANY = A.COMPANY AND B.DOCU_NO = A.DOCU_NO AND A.CUR_ORDER_NO = B.ORDER_NO AND TO_CHAR(START_DATE,'YYYYMMDD') BETWEEN replace(#{startDate},'/','') AND replace(#{endDate},'/','')
AND A.EXTIF_TP = #{st_gubun}
AND A.PASS_STATUS = #{st_status}
AND A.DOCU_TITLE LIKE '%'||#{st_subject}||'%' ORDER BY A.START_DATE DESC
) X )Y WHERE Y.NUM BETWEEN #{startrow} AND #{endrow} ORDER BY Y.START_DATE DESC

mapper.update:
/*commonApproval.modfiySetRefer1*/
UPDATE	ICOGPASSLN
SET		REFER_DATE = SYSDATE,
		PASS_DATE = SYSDATE,
		PASS_KN = '2'
WHERE	1=1
AND		COMPANY = #{COMPANY}
AND		DOCU_NO = #{DOCU_NO}
AND		USER_ID IN (SELECT CODE1 FROM ICOMCOD3 WHERE TYPE = 'M-APPR' AND FLAG = 'Y' AND CODE2 = #{USER_ID} UNION SELECT #{USER_ID} FROM DUAL)
AND		ORDER_NO = (SELECT MIN(ORDER_NO) FROM ICOGPASSLN WHERE COMPANY = #{COMPANY} AND DOCU_NO = #{DOCU_NO} AND USER_ID IN (SELECT CODE1 FROM ICOMCOD3 WHERE TYPE = 'M-APPR' AND FLAG = 'Y' AND CODE2 = #{USER_ID} UNION SELECT #{USER_ID} FROM DUAL) AND REFER_DATE IS NULL)

/*commonApproval.modfiySetRefer2*/
UPDATE	ICOGPASSLN
SET		REFER_DATE = SYSDATE 
WHERE	1=1
AND		COMPANY = #{COMPANY}
AND		DOCU_NO = #{DOCU_NO}
AND		USER_ID IN (SELECT CODE1 FROM ICOMCOD3 WHERE TYPE = 'M-APPR' AND FLAG = 'Y' AND CODE2 = #{USER_ID} UNION SELECT #{USER_ID} FROM DUAL)
AND		ORDER_NO = (SELECT MIN(ORDER_NO) FROM ICOGPASSLN WHERE COMPANY = #{COMPANY} AND DOCU_NO = #{DOCU_NO} AND USER_ID IN (SELECT CODE1 FROM ICOMCOD3 WHERE TYPE = 'M-APPR' AND FLAG = 'Y' AND CODE2 = #{USER_ID} UNION SELECT #{USER_ID} FROM DUAL) AND REFER_DATE IS NULL)

mapper.select:
  /*commonApproval.getBuyerCommonPrPxData*/
        SELECT
        	SUM(CASE WHEN A.RECV_FLAG IN ('GR','PR','RR') THEN TRUNC(NVL(A.TARGET_QTY,0) * NVL(A.TARGET_PRICE,0)) END) AS R_AMT
            ,SUM(CASE WHEN A.RECV_FLAG NOT IN ('GR','PR','RR') THEN TRUNC(NVL(A.TARGET_QTY,0) * NVL(A.TARGET_PRICE,0)) END) AS PRICE
        	,COUNT(*) AS CNT
        FROM ICOMPRDT A
        WHERE A.BUYER = #{COMPANY}

    	    AND A.PR_NO = #{key_1}

				AND A.RECV_FLAG NOT IN ('GR','PR','RR')



    	    AND A.REF_NO = #{key_1}

				AND A.RECV_FLAG NOT IN ('GR','PR')


        AND A.STATUS != 'D'

/*commonApproval.getBuyerCommonNgNsData*/ SELECT COUNT(*) AS CNT ,SUM(A.ATOB_UNIT_PRICE) AS PRICE FROM KEPRQDT A
, KEPQTDT B
WHERE A.BUYER IN (SELECT CODE2 FROM ICOMCOD3 WHERE BUYER = #{COMPANY} AND TYPE = 'TGCM' AND CODE1 = #{USER_ID} AND FLAG = 'Y' UNION SELECT #{COMPANY} FROM DUAL)
AND A.GW_GA_NO = #{key_1}
AND A.GW_NO = #{key_1} AND B.BID_SUCCESS_FLAG = 'Y' AND A.ATOB_SEND_FLAG = 'Y' AND A.BUYER = B.BUYER AND A.QUOTATION_NO = B.QUOTATION_NO AND A.QUOTATION_SEQ = B.QUOTATION_SEQ AND A.REVISION=B.REVISION AND B.STATUS != 'D' AND B.STATUS != 'O'
AND A.STATUS != 'D' AND A.SO_CA_FLAG='SO' AND A.STATUS IN ('C','R','O')

mapper.update:
	   /*commonApproval.modifyICOGPASSLN*/ 
	   /* PASS_KN	  결재상태(NULL:미결재,0:기안,1:승인,2:참조,3:반려,4:상신취소,9:임시저장) */

			UPDATE	ICOGPASSLN
			SET		PASS_DATE = SYSDATE,
					PASS_KN = #{PASS_KN},
					PASS_ADD = #{PASS_ADD}  
            WHERE	1=1
            AND		COMPANY = #{COMPANY}
            AND		DOCU_NO = #{DOCU_NO}
            AND		USER_ID IN (SELECT CODE1 FROM ICOMCOD3 WHERE TYPE = 'M-APPR' AND FLAG = 'Y' AND CODE2 = #{USER_ID} UNION SELECT #{USER_ID} FROM DUAL)
            AND		PASS_DATE IS NULL
            AND		PASS_TP <> 0

mapper.select:
  /*commonApproval.getICOGPASSLNOrderNo*/     
   /* PASS_TP 	결재구분(0:기안,1:결재,2:참조,3:합의) */

                   SELECT 
                   		''||ORDER_NO ORDER_NO
                   FROM
				   ICOGPASSLN 
                   WHERE 
	                   COMPANY = #{COMPANY} 
