SELECT Z.COMPANY, Z.DOCU_NO, Z.DOCU_TITLE, Z.START_DATE, Z.USER_NM, Z.EXTIF_TP_TEXT, Z.EXTIF_TP, Z.ORDER_DEPT, Z.ITEM_CNT, Z.ORDER_AMT, Z.ORDER_DEPT_CD, Z.KEY1, PRDT.BUYER_ITEM_NO, PRDT.DESCRIPTION, PRDT.SPECIFICATION, PRDT.UNIT_MEASURE, PRDT.TARGET_QTY, PRDT.TARGET_PRICE, NVL(PRDT.TARGET_QTY, 0) * NVL(PRDT.TARGET_PRICE, 0) AS PRDT_AMT, PRDT.RD_DATE, PRDT.BUDGET_DEPT, (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = Z.COMPANY AND CODE = PRDT.BUDGET_DEPT) AS BUDGET_DEPT_TEXT, PRDT.ACCOUNT_TYPE, (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'Z014' AND COMPANY_CODE = Z.COMPANY AND CODE = PRDT.ACCOUNT_TYPE) AS ACCOUNT_TYPE_TEXT, PRDT.DELY_TO_LOCATION, (SELECT TEXT2 FROM ICOMCOD2 WHERE TYPE = 'C012' AND COMPANY_CODE = Z.COMPANY AND CODE = PRDT.DELY_TO_LOCATION) AS DELY_TO_LOCATION_TEXT, DECODE(PRDT.IMAGE_KEY, '', 'N', 'Y') AS ATTACH_CNT FROM ( SELECT Y.COMPANY, Y.DOCU_NO, Y.DOCU_TITLE, DECODE(Y.EXTIF_TP, 'PX', (SELECT TO_CHAR(START_DATE, 'YYYY/MM/DD') FROM ICOGDOCU WHERE COMPANY = Y.COMPANY AND DOCU_NO = (SELECT MAX(TARGET) FROM ICOMTRGW WHERE COM_CODE = Y.COMPANY AND DOC_NAME = 'PR' AND KEY_1 = Y.KEY1)),Y.START_DATE) AS START_DATE, Y.USER_NM, Y.EXTIF_TP_TEXT, Y.EXTIF_TP, NVL(Y.ORDER_DEPT,(SELECT D.TEXT1 FROM ICOMCOD2 D WHERE D.COMPANY_CODE=Y.COMPANY AND D.TYPE='C001' AND D.CODE=Y.DEPARTMENT)) ORDER_DEPT, Y.ITEM_CNT, Y.ORDER_AMT, NVL(Y.ORDER_DEPT_CD,Y.DEPARTMENT) ORDER_DEPT_CD, Y.KEY1, Y.ATTACH_CNT FROM ( SELECT X.COMPANY, X.DOCU_NO, X.DOCU_TITLE, X.START_DATE, X.USER_NM, X.EXTIF_TP_TEXT, X.EXTIF_TP, X.ITEM_CNT, X.ORDER_AMT, X.ORDER_DEPT, X.ORDER_DEPT_CD, X.KEY1, X.ATTACH_CNT, (SELECT DEPARTMENT FROM ICOMLUSR WHERE USER_ID = X.USER_ID) DEPARTMENT FROM ( SELECT A.COMPANY, A.DOCU_NO, A.DOCU_TITLE, A.ATTACH_CNT, DECODE(C.PASS_TP,'1','결재문서','2','참조문서','3','합의문서') GUBUN, TO_CHAR(A.START_DATE, 'YYYY/MM/DD' ) START_DATE, START_DATE START_DATE2, decode( #{USERID}, B.USER_ID, '결재요망' ,(SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = B.USER_ID)) NEXT_USER_NM, A.DOCU_KN, A.USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.USER_ID) ADD_USER_ID, C.PASS_TP, NVL(C.PASS_KN,'0') PASS_KN, A.USER_NM USER_NM, B.USER_ID AS NEXT_USER_ID, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'APPR' AND CODE = A.EXTIF_TP) AS EXTIF_TP_TEXT, A.EXTIF_TP AS EXTIF_TP, DECODE(TRGW.DOC_NAME,'PR', (SELECT COUNT(*) FROM ICOMPRDT WHERE BUYER = TRGW.COM_CODE AND PR_NO = TRGW.KEY_1 AND STATUS ^= 'D'), 'PX', (SELECT COUNT(*) FROM ICOMPRDT WHERE BUYER = TRGW.COM_CODE AND REF_NO = TRGW.KEY_1 AND STATUS ^= 'D'),NULL) AS ITEM_CNT, DECODE(TRGW.DOC_NAME,'PR', (SELECT SUM(TARGET_QTY*TARGET_PRICE) FROM ICOMPRDT WHERE BUYER = TRGW.COM_CODE AND PR_NO = TRGW.KEY_1 AND STATUS ^= 'D'), 'PX', (SELECT SUM(RECV_QTY*TARGET_PRICE) FROM ICOMPRDT WHERE BUYER = TRGW.COM_CODE AND REF_NO = TRGW.KEY_1 AND STATUS ^= 'D'),NULL) AS ORDER_AMT, DECODE(TRGW.DOC_NAME,'PR', (SELECT MAX(COD2.TEXT1)||DECODE(COUNT(DISTINCT CHANGE_USER_DEPT),1,NULL, ' 외 '||TO_CHAR(COUNT(DISTINCT CHANGE_USER_DEPT)-1)||'개') FROM ICOMPRDT, ICOMCOD2 COD2 WHERE BUYER = TRGW.COM_CODE AND PR_NO = TRGW.KEY_1 AND STATUS ^= 'D' AND BUYER = COD2.COMPANY_CODE AND COD2.TYPE = 'C001' AND COD2.CODE =CHANGE_USER_DEPT ), 'PX', (SELECT MAX(COD2.TEXT1)||DECODE(COUNT(DISTINCT CHANGE_USER_DEPT),1,NULL, ' 외 '||TO_CHAR(COUNT(DISTINCT CHANGE_USER_DEPT)-1)||'건') FROM ICOMPRDT, ICOMCOD2 COD2 WHERE BUYER = TRGW.COM_CODE AND REF_NO = TRGW.KEY_1 AND STATUS ^= 'D' AND BUYER = COD2.COMPANY_CODE AND COD2.TYPE = 'C001' AND COD2.CODE =CHANGE_USER_DEPT),NULL) AS ORDER_DEPT, DECODE(TRGW.DOC_NAME,'PR', (SELECT MAX( CHANGE_USER_DEPT) FROM ICOMPRDT, ICOMCOD2 COD2 WHERE BUYER = TRGW.COM_CODE AND PR_NO = TRGW.KEY_1 AND STATUS ^= 'D' AND BUYER = COD2.COMPANY_CODE AND COD2.TYPE = 'C001' AND COD2.CODE =CHANGE_USER_DEPT ), 'PX', (SELECT MAX(CHANGE_USER_DEPT) FROM ICOMPRDT, ICOMCOD2 COD2 WHERE BUYER = TRGW.COM_CODE AND REF_NO = TRGW.KEY_1 AND STATUS ^= 'D' AND BUYER = COD2.COMPANY_CODE AND COD2.TYPE = 'C001' AND COD2.CODE =CHANGE_USER_DEPT),NULL) AS ORDER_DEPT_CD, DECODE(TRGW.DOC_NAME, 'PX', (SELECT MAX(PR_NO) FROM ICOMPRDT WHERE BUYER = TRGW.COM_CODE AND REF_NO = TRGW.KEY_1 AND STATUS != 'D'), TRGW.KEY_1) AS KEY1 FROM ICOGDOCU A, ICOGPASSLN B, (SELECT Y.COMPANY, Y.DOCU_NO, Y.PASS_TP, Y.PASS_KN,Y.ORDER_NO FROM ICOGDOCU X, ICOGPASSLN Y WHERE X.COMPANY=#{BUYER} AND X.START_DATE BETWEEN to_date(#{startDate},'YYYY/MM/DD') AND to_date(#{endDate},'YYYY/MM/DD')+1 AND X.PASS_STATUS = '0' AND X.COMPANY=Y.COMPANY AND X.DOCU_NO=Y.DOCU_NO AND Y.USER_ID = #{USERID} AND Y.ORDER_NO > 1 AND Y.DISPLAY_YN = 'Y') C ,ICOMTRGW TRGW WHERE ((C.PASS_TP = '1' AND A.DOCU_NO = C.DOCU_NO AND A.COMPANY = C.COMPANY AND A.PASS_STATUS = '0' AND C.PASS_KN IS NULL ) OR (C.PASS_TP = '3' AND A.DOCU_NO = C.DOCU_NO AND A.COMPANY = C.COMPANY AND A.PASS_STATUS = '0' AND C.PASS_KN IS NULL)) AND A.COMPANY = B.COMPANY AND A.DOCU_NO = B.DOCU_NO AND A.CUR_ORDER_NO = B.ORDER_NO AND A.COMPANY = TRGW.COM_CODE AND A.DOCU_NO = TRGW.TARGET AND C.COMPANY = A.COMPANY AND C.DOCU_NO = A.DOCU_NO AND C.COMPANY = TRGW.COM_CODE AND C.DOCU_NO = TRGW.TARGET AND C.PASS_TP IN ('1', '3') AND B.USER_ID = #{USERID}
AND A.USER_NM like '%'||#{st_drafter} ||'%'
