ORDER BY START_DATE2 DESC ) X WHERE 1=1
AND X.ORDER_DEPT_CD = #{st_req_dept_code}
)Y ) Z, ICOMPRDT PRDT WHERE 1=1 AND Z.COMPANY = PRDT.BUYER AND Z.KEY1 = PRDT.PR_NO AND PRDT.STATUS ^= 'D'

/*getprDocuNo*/

SELECT	DECODE(COUNT(*), 0, 'NULL', MAX(TARGET)) AS TARGET
FROM	ICOMTRGW
WHERE	1=1
AND		COM_CODE = #{COMPANY}
AND		KEY_1 = (
		SELECT	MAX(PR_NO)
		FROM	ICOMPRDT
		WHERE	1=1
		AND		(BUYER, REF_NO) IN (
				SELECT	COM_CODE, KEY_1
				FROM	ICOMTRGW
				WHERE	1=1
				AND		COM_CODE = #{COMPANY}
				AND		TARGET = #{DOCU_NO}
		)
)

